    # Removes a file, a link or a directory (recursive for one with contents). One missing is success, removed false.
    def remove(id, path:, recursive: nil, idempotency_key: nil)
      FileRemoved.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}/files:remove", body: { "path" => path, "recursive" => recursive }.compact, idempotency_key: idempotency_key))
    end

    # Returns what is at a path: a file, a directory or a link, or nothing (exists false). With sha256=true, a file's SHA-256 too.
    def stat(id, path:, sha256: nil)
      FileInfo.from(@transport.request("GET", "/v2/sites/#{URI.encode_www_form_component(id)}/files/stat", query: { "path" => path, "sha256" => sha256 }, idempotent: true))
    end

    # Lists a directory's entries in path order, to a depth.
    def list_files(id, path: nil, depth: nil, limit: nil, hidden: nil, glob: nil)
      FileList.from(@transport.request("GET", "/v2/sites/#{URI.encode_www_form_component(id)}/files/list", query: { "path" => path, "depth" => depth, "limit" => limit, "hidden" => hidden, "glob" => glob }, idempotent: true))
    end

    # Returns a folder as a tar archive (`application/x-tar`, or `application/gzip` with gzip), packed by tar in the site as it streams, of any size; its entries are relative to the folder (`./a.txt`). A folder that fails part way (a file it may not read, or one that changes as it is read) ends as an archive every tar reader refuses, never as a short one that reads whole. At most 4 at once in a site. A paused site is woken first.
    def download_folder(id, path:, gzip: nil, user: nil, exclude: nil)
      @transport.request("GET", "/v2/sites/#{URI.encode_www_form_component(id)}/files/archive", query: { "path" => path, "gzip" => gzip, "user" => user, "exclude" => exclude }, raw: true, idempotent: true)
    end

    # Unpacks the request's tar archive (gzip-compressed or not, told by its first bytes) into a folder, made with its parents, by tar in the site as the bytes arrive, of any size, nothing of it kept on disk but what tar writes; returns once tar has ended, or 400 `invalid_archive` with what tar said. A paused site is woken first.
    def upload_folder(id, data, path:, user: nil, idempotency_key: nil)
      FolderUnpacked.from(@transport.request("PUT", "/v2/sites/#{URI.encode_www_form_component(id)}/files/archive", query: { "path" => path, "user" => user }, data: data, idempotency_key: idempotency_key, idempotent: true))
    end

    # Begins a folder's upload in parts: tar starts in the site, unpacking into the folder each part as it arrives. Send the parts in order by offset (writeFolderUpload), then commitFolderUpload; an upload no call names for 10 minutes is ended. A paused site is woken first.
    def begin_folder_upload(id, path:, gzip: nil, user: nil, idempotency_key: nil)
      FolderUpload.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}/files/archive/uploads", body: { "path" => path, "gzip" => gzip, "user" => user }.compact, idempotency_key: idempotency_key))
    end

    # Sends the request's bytes, a part of the archive at its offset, into tar's input as they arrive, of any size, and returns the bytes received in all once tar took them. A part past them is refused 409 `upload_incomplete`, naming them: send the parts in order.
    def write_folder_upload(id, upload, data, offset: nil, idempotency_key: nil)
      FolderUploadReceived.from(@transport.request("PUT", "/v2/sites/#{URI.encode_www_form_component(id)}/files/archive/uploads/#{URI.encode_www_form_component(upload)}", query: { "offset" => offset }, data: data, idempotency_key: idempotency_key, idempotent: true))
    end

    # Ends a folder upload's input and returns once tar has ended, as an exec returns once its command has: the folder, or 400 `invalid_archive` with what tar said. A front that restarts meanwhile returns 503 `run_goes_on`; sent again, it returns how tar ended. An upload no call has named for 10 minutes since its last part or commit is ended.
    def commit_folder_upload(id, upload, idempotency_key: nil)
      FolderUnpacked.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}/files/archive/uploads/#{URI.encode_www_form_component(upload)}:commit", idempotency_key: idempotency_key, idempotent: true))
    end

    # Stops a folder upload's tar; what it unpacked so far stays.
    def abort_folder_upload(id, upload, idempotency_key: nil)
      FolderUploadAborted.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}/files/archive/uploads/#{URI.encode_www_form_component(upload)}:abort", idempotency_key: idempotency_key, idempotent: true))
    end

    # Makes a directory, and its parents unless parents is false. One there already is success, created false.
    def mkdir(id, path:, parents: nil, idempotency_key: nil)
      FileMade.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}/files:mkdir", body: { "path" => path, "parents" => parents }.compact, idempotency_key: idempotency_key, idempotent: true))
    end

    # Moves a file, a link or a directory; refused 409 when something is at its new path, unless overwrite. With sha256 or size, a file written in parts is put in place once whole: its writes ended, then only a file of that size with every byte written and whose bytes hash to it moves; refused 409 `upload_incomplete` or `checksum_mismatch`, nothing moved. With sha256, it is safe to send again: once moved, it returns the same answer while `from` is gone and `to` holds those bytes.
    def rename(id, from:, to:, overwrite: nil, sha256: nil, size: nil, idempotency_key: nil)
      FileRenamed.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}/files:rename", body: { "from" => from, "to" => to, "overwrite" => overwrite, "sha256" => sha256, "size" => size }.compact, idempotency_key: idempotency_key))
    end

    # Makes an expiring address for one file that anyone may open with no API key, from a browser, curl or another service: GET downloads it (Range works, so videos play and downloads resume; archive: true downloads a folder as .tar.gz), PUT with the raw body uploads it (up to maxBytes, written whole; Content-Length required). The link acts as the key that made it: an upload link needs write, and the link ends with its key, with revokeLinks or with its site. A paused site is woken for it unless wake is false.
    def link(id, path:, method: nil, expires_in_seconds: nil, filename: nil, max_bytes: nil, wake: nil, archive: nil, idempotency_key: nil)
      FileLink.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}/files:link", body: { "path" => path, "method" => method, "expiresInSeconds" => expires_in_seconds, "filename" => filename, "maxBytes" => max_bytes, "wake" => wake, "archive" => archive }.compact, idempotency_key: idempotency_key))
    end

    # Ends every file link made for a site so far; links made after work.
    def revoke_links(id, idempotency_key: nil)
      FileLinksRevoked.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}/files:revokeLinks", idempotency_key: idempotency_key))
    end

    # Returns where a site may connect out.
    def get_network(id)
      SandboxNetwork.from(@transport.request("GET", "/v2/sites/#{URI.encode_www_form_component(id)}/network", idempotent: true))
    end

    # Returns a site's CPU, memory, disks and pressure, as its host reads them from the site's own cgroup over a fifth of a second: never a call into the site, so it does not wake a paused one nor keep one from its idle pause. One that is not running has no reading.
    def metrics(id, range: nil)
      SandboxMetrics.from(@transport.request("GET", "/v2/sites/#{URI.encode_www_form_component(id)}/metrics", query: { "range" => range }, idempotent: true))
    end

    # Replaces where a site may connect out, for its next connection and within a second for its open ones: those the new rules refuse are cut.
    def set_network(id, allow_outbound: nil, deny_outbound: nil, idempotency_key: nil)
      SandboxNetwork.from(@transport.request("PUT", "/v2/sites/#{URI.encode_www_form_component(id)}/network", body: { "allowOutbound" => allow_outbound, "denyOutbound" => deny_outbound }.compact, idempotency_key: idempotency_key))
    end

    # Copies a site as it is now, memory and disk, into `count` copies of its own, each running on its host. Asked again with the same Idempotency-Key, it returns the same copies.
    def fork(id, count: nil, name: nil, labels: nil, secrets: nil, max_cost: nil, idle_pause_seconds: nil, vcpu: nil, delete_after_seconds: nil, delete_protection: nil, idempotency_key: nil)
      Forked.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}:fork", body: { "count" => count, "name" => name, "labels" => labels, "secrets" => secrets, "maxCost" => max_cost, "idlePauseSeconds" => idle_pause_seconds, "vcpu" => vcpu, "deleteAfterSeconds" => delete_after_seconds, "deleteProtection" => delete_protection }.compact, idempotency_key: idempotency_key, idempotent: true))
    end

    # Keeps a site's memory and disk as they are now, a snapshot to start sites from; with `image`, its disk alone as that image's next version. The site runs on. Asked again with the same Idempotency-Key, it returns the same snapshot.
    def snapshot(id, name: nil, labels: nil, image: nil, start: nil, delete_after_seconds: nil, delete_protection: nil, idempotency_key: nil)
      Stored.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}:snapshot", body: { "name" => name, "labels" => labels, "image" => image, "start" => start, "deleteAfterSeconds" => delete_after_seconds, "deleteProtection" => delete_protection }.compact, idempotency_key: idempotency_key, idempotent: true))
    end

    # Changes its name, labels, idle pause, maxCost, autoWake, lifetime, delete protection, environment or sizes; each field left out stays as it is. A lifetime (`deleteAfterSeconds`) sent again before its end moves the end to that many seconds from now; 0 takes it off. A lifetime is refused (409 `delete_protected`) while `deleteProtection` is true. A running one holds a changed environment before this answers (a paused one's at its wake): each process it starts after the answer has it, and its running processes keep the one they started with. Its vCPUs, memory and disk grow while it runs, its commands running on. One paused or stopped is not woken for it: judged at once as a live resize is (past the vCPUs it was made with 409, over its organization's limits `quota_exceeded`), its new sizes are returned at once, and its next wake grows it to them before the call that woke it runs. A smaller size, or a machine starting or failed, is refused 409 naming why, and nothing is changed. With If-Match, made only while its revision is that one, else 412. Sent again with the same Idempotency-Key and body while it is the latest change, it returns the current state and changes nothing; the same key with a different body returns 409 idempotency_key_reused.
    def update(id, name: nil, labels: nil, idle_pause_seconds: nil, vcpu: nil, memory_gb: nil, disk_gb: nil, user: nil, env: nil, remove_env: nil, max_cost: nil, auto_wake: nil, delete_after_seconds: nil, delete_protection: nil, idempotency_key: nil)
      SandboxInfo.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}:update", body: { "name" => name, "labels" => labels, "idlePauseSeconds" => idle_pause_seconds, "vcpu" => vcpu, "memoryGB" => memory_gb, "diskGB" => disk_gb, "user" => user, "env" => env, "removeEnv" => remove_env, "maxCost" => max_cost, "autoWake" => auto_wake, "deleteAfterSeconds" => delete_after_seconds, "deleteProtection" => delete_protection }.compact, idempotency_key: idempotency_key))
    end

    # Returns what a site's screen shows now, as `image/png` (or `image/jpeg`): its X display `:1`, whole. Refused 409 `display_not_running` when no display runs. A paused site is resumed first.
    def screenshot(id, format: nil, quality: nil)
      @transport.request("GET", "/v2/sites/#{URI.encode_www_form_component(id)}/screenshot", query: { "format" => format, "quality" => quality }, raw: true, idempotent: true)
    end

    # Moves, clicks, drags and scrolls the mouse and types on the keyboard of a site's screen (its X display `:1`), each step in turn as one command, and returns where the mouse is then. It stops at the first step that fails, refused 409 `act_failed` naming it; refused 409 `display_not_running` when no display runs. A paused site is resumed first.
    def act(id, actions:, idempotency_key: nil)
      Acted.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}:act", body: { "actions" => actions }.compact, idempotency_key: idempotency_key))
    end

    # Runs a cell of Python in a site as a notebook does, in a Jupyter kernel it keeps running for the cell's `context`: variables, imports and functions stay for the next cell. Returns what it printed, its values and displays (text, HTML, images such as charts), and its exception with its traceback. The context's kernel starts on its first cell. A cell past `timeoutSeconds` is interrupted and its context kept. Refused 409 `kernel_not_installed` when the image has no ipykernel. A paused site is resumed first.
    def run_code(id, code:, language: nil, context: nil, timeout_seconds: nil, idempotency_key: nil)
      CodeRun.from(@transport.request("POST", "/v2/sites/#{URI.encode_www_form_component(id)}:runCode", body: { "code" => code, "language" => language, "context" => context, "timeoutSeconds" => timeout_seconds }.compact, idempotency_key: idempotency_key))
    end
  end
end
